"""Compute test/fixtures/v1/expected.json from the fixture files with Python's json module.

The expected values come from an INDEPENDENT reader (Python's json, not AtlasIO), so the tests do not
check AtlasIO against itself. District keys are decoded with json.loads, the correct reading of the v1
key strings. Run from the repository root, after generate_v1_fixtures.jl and make_python_fixture.py:
    python3 test/fixtures/make_expected.py
"""
import bz2
import gzip
import hashlib
import json
import os
import re

HERE = os.path.dirname(os.path.abspath(__file__))
V1 = os.path.join(HERE, "v1")
REPO = os.path.normpath(os.path.join(HERE, "..", ".."))
NC_REL = "ExampleAtlas/atlas_truncated_nc_multiscale.jsonl"

FIXTURES = ["edge.jsonl", "edge.jsonl.gz", "edge_multimember.jsonl.gz", "edge.jsonl.bz2",
            "edge_float.jsonl", "python_written.jsonl"]

# A backslash escape other than \" or \\ inside a key string: AtlasIO 0.1.5's parseDistrictKey drops the
# backslash and keeps the next character literally, so it mis-decodes such keys. Escapes are read in pairs,
# left to right (so the "\\" in "c\\d" is one escape, not a backslash followed by "\d").
ESCAPE = re.compile(r"\\(.)", re.DOTALL)


def misdecoded_by_julia_0_1_5(raw_key):
    return any(m.group(1) not in '"\\' for m in ESCAPE.finditer(raw_key))


def read_text(path):
    opener = {".gz": gzip.open, ".bz2": bz2.open}.get(os.path.splitext(path)[1], open)
    with opener(path, "rt", encoding="utf-8") as f:
        return f.read()


def parse_atlas(text):
    # Real v1 files may lack a final newline (the NC example does); readers must accept both.
    lines = text.split("\n")
    if lines[-1] == "":
        lines = lines[:-1]
    header, params = json.loads(lines[1]), json.loads(lines[2])
    maps = []
    for line in lines[3:]:
        m = json.loads(line)
        assert list(m) == ["name", "weight", "data", "districting"], list(m)
        raw_keys = [k for entry in m["districting"] for k in entry]
        maps.append({
            "name": m["name"], "weight": m["weight"], "data": m["data"],
            "districting": sorted([json.loads(k), v] for entry in m["districting"] for k, v in entry.items()),
            "julia_0_1_5_misdecodes_keys": any(misdecoded_by_julia_0_1_5(k) for k in raw_keys),
        })
    return header, params, maps


def districting_digest(pairs):
    """Order-independent fingerprint of a districting; tests compute the same thing from what they read."""
    lines = sorted("\x1f".join(keyparts) + "\x1e" + str(v) for keyparts, v in pairs)
    return hashlib.sha256("\n".join(lines).encode("utf-8")).hexdigest()


expected = {"_about": "Generated by test/fixtures/make_expected.py from the frozen v1 fixtures. Do not edit by hand.",
            "fixtures": {}}

texts = {}
for name in FIXTURES:
    texts[name] = read_text(os.path.join(V1, name))
    header, params, maps = parse_atlas(texts[name])
    expected["fixtures"][name] = {"header": header, "atlasParam": params, "maps": maps}

# The four encodings of the edge atlas must hold identical content.
assert texts["edge.jsonl"] == texts["edge.jsonl.gz"] == texts["edge_multimember.jsonl.gz"] == texts["edge.jsonl.bz2"]

nc_path = os.path.join(REPO, NC_REL)
with open(nc_path, "rb") as f:
    nc_sha = hashlib.sha256(f.read()).hexdigest()
header, params, maps = parse_atlas(read_text(nc_path))
expected["nc_truncated"] = {
    "path": NC_REL, "sha256": nc_sha, "header": header, "atlasParam": params,
    "ends_with_newline": read_text(nc_path).endswith("\n"),
    "maps": [{"name": m["name"], "weight": m["weight"], "data": m["data"],
              "n_districting": len(m["districting"]), "districting_digest": districting_digest(m["districting"])}
             for m in maps],
}

with open(os.path.join(V1, "expected.json"), "w", encoding="utf-8", newline="\n") as f:
    json.dump(expected, f, ensure_ascii=False, indent=1, sort_keys=True)
    f.write("\n")
print("wrote", os.path.join(V1, "expected.json"),
      "| fixtures:", len(FIXTURES), "| NC maps:", len(maps),
      "| Julia-misdecoded maps:", [(n, m["name"]) for n in FIXTURES
                                   for m in expected["fixtures"][n]["maps"] if m["julia_0_1_5_misdecodes_keys"]])
